/// A module value's type, as printed (C172): its abstract types named for
/// its binding, `n..t`, its own again, shown `t`, as Fixpt prints them.
pub fn own_abstract(n: Str, t: &'static Ty) -> &'static Ty {
    if mtype_p(t) {
        let mine = onto(data_names_with(string_append(n, str_lit("..")), t), data_names_with(str_lit("made--load--"), t));
        data_renamed(mine, map(lambda1s(move |r: Str| {
            string_append(str_lit("mt@0.."), after_dots(r))
        }), mine), t)
    } else {
        t
    }
}

/// A definition's line: its name, its type as the checker has it, inside
/// its written binders, and the effect of making its value.
pub fn bound_line(v: &'static Cv, n: Str, written: &'static Sexp, effect: Str) -> Str {
    let found = scope_bind(n, v);
    if null_p(found) {
        string_append(str_lit("define "), n)
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n2, sc, w) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tvars, t) => {
                        string_append(str_lit("define "), string_append(n, string_append(str_lit(" : "), string_append(poly_wrapped(written, written_shown(v, written, own_abstract(n, t))), string_append(str_lit(" ! "), effect)))))
                    }
                }
            }
        }
    }
}

pub fn no_form() -> &'static Sexp {
    lst(nil::<&'static Sexp>(), str_lit(""), 0i64, 0i64)
}

pub fn chars_ahead_of(cs: Chars, pat: Chars) -> Chars {
    if (null_p(cs) || chars_start_p(cs, pat)) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), chars_ahead_of(cdr(cs), pat))
    }
}

/// A generative type's conversion's line: its type inside its family's
/// binders `w`, if any.
pub fn generative_line(v: &'static Cv, n: Str, w: &'static Sexp) -> Str {
    let line = bound_line(v, n, no_form(), str_lit("pure"));
    if head_is_p(w, str_lit("poly")) {
        let at = string_append(str_lit("define "), string_append(n, str_lit(" : ")));
        let rest = after_prefix(line, at);
        let ty = list_to_string(chars_ahead_of(string_chars(rest), string_chars(str_lit(" ! "))));
        string_append(at, string_append(poly_wrapped(w, ty), after_prefix(rest, ty)))
    } else {
        line
    }
}

/// Each atom once: two may resolve to one, a region solved after (C188).
pub fn atoms_once(mut es: Strings, mut seen: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if string_member_p(car(es), seen) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), atoms_once(cdr(es), kayak_rt::heap_cons(car(es), seen)));
        }
    }
}

/// An effect as printed (C166): its regions as solved; an allocation at
/// `acyclic`, or at a region still unsolved, nothing, as Fixpt's.
pub fn settled_effs(s: &'static St, es: Strings) -> Strings {
    filter(lambda1s(move |a: Str| {
        not((string_eq_p(a, str_lit("alloc:acyclic")) || has_prefix_p(a, str_lit("alloc:?")) || string_eq_p(a, str_lit("goto:acyclic")) || string_eq_p(a, str_lit("comefrom:acyclic"))))
    }), atoms_once(map(lambda1s(move |a: Str| {
        resolve_atom(s, a)
    }), es), nil::<Str>()))
}

/// The effect of evaluating `n`'s value `e`, checked against its type as
/// the checker checks a constant's: none for a procedure.
pub fn value_effect(v: &'static Cv, n: Str, e: &'static Sexp) -> Str {
    let found = scope_bind(n, v);
    if (null_p(found) || lambda_form_p(e)) {
        str_lit("pure")
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n2, sc, w) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tvars, t) => {
                        if null_p(tvars) {
                            let tagcase_ = expressions::check(at(v, str_lit("a definition's value"), nil::<Str>()), new_state(), e, t);
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    show_effs(settled_effs(s, es))
                                }
                            }
                        } else {
                            str_lit("pure")
                        }
                    }
                }
            }
        }
    }
}

/// The type written for global `n` among the program's `forms`, if one is.
pub fn written_of(mut n: Str, mut forms: Sexps) -> Sexps {
    loop {
        if null_p(forms) {
            return nil::<&'static Sexp>();
        } else {
            let f = car(forms);
            if ((head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) && i64_eq(size(items(f)), 4i64) && {
                let tagcase_ = second(items(f));
                match *tagcase_ {
                    Sexp::Sym(m, f2, p2) => {
                        string_eq_p(m, n)
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                return the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()));
            } else {
                forms = cdr(forms);
                continue;
            }
        }
    }
}

/// An expression's type as printed: a call's, each abbreviation its
/// callee's written type names by name (C164), as Fixpt's types keep them.
pub fn call_shown(v: &'static Cv, all: Sexps, form: &'static Sexp, shown: Str) -> Str {
    let w = {
        let tagcase_ = form;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                if (not(null_p(xs)) && {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                }) {
                    written_of(sym_name(car(xs)), all)
                } else {
                    nil::<&'static Sexp>()
                }
            }
            _ => {
                let other = tagcase_;
                nil::<&'static Sexp>()
            }
        }
    };
    if (null_p(w) || written_mentions_p(car(w), kayak_rt::heap_cons(str_lit("%found"), kayak_rt::heap_cons(str_lit("->*"), kayak_rt::heap_cons(str_lit("select"), kayak_rt::heap_cons(str_lit("moduleof"), kayak_rt::heap_cons(str_lit("dlambda"), kayak_rt::nil()))))))) {
        shown
    } else {
        abbrevs_put(shown, abbrevs_in(parse_type(v, kayak_rt::heap_cons(str_lit("%keep-names"), written_tvars(written_binders(v, car(w)))), written_body(car(w)))))
    }
}

// A module's line (C165), as Fixpt's: `define m : (moduleof (desc t T) ...
// (abs t type) ... (val x T) ...) ! E`, its types' descriptions first, then
// its values, each in the order written, an `include`d module's in its
// place, a hidden item left out; each type as written, its abbreviations
// by name. What this does not print (a datatype, an `extend`, an `import`,
// a type found, `->*`'s, a module type), the line is left out, as before.
pub enum Qual {
    Qual(Str, &'static Sexp, bool),
}

pub fn qual(f0: Str, f1: &'static Sexp, f2: bool) -> &'static Qual {
    kayak_rt::heap_alloc(Qual::Qual(f0, f1, f2))
}

pub type Quals = List<&'static Qual>;

/// The module definition of `n` among the program's forms, if one is.
pub fn module_of(n: Str, all: Sexps) -> Sexps {
    filter(lambda1s(move |f: &'static Sexp| {
        (module_def_p(f) && head_is_p(third(items(f)), str_lit("module")) && {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(m, f2, p2) => {
                    string_eq_p(m, n)
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        })
    }), all)
}

/// Whether `body` applies a family, whose abbreviation Fixpt's types do not
/// keep by name.
pub fn family_app_p(v: &'static Cv, body: &'static Sexp) -> bool {
    let tagcase_ = body;
    match *tagcase_ {
        Sexp::Lst(ys, f, l, p) => {
            (not(null_p(ys)) && not(sym_is_p(car(ys), str_lit("select"))) && {
                let tagcase_ = car(ys);
                match *tagcase_ {
                    Sexp::Sym(h, f2, p2) => {
                        let found = find_alias(h, cv_aliases(v));
                        (not(null_p(found)) && {
                            let tagcase_ = car(found);
                            match *tagcase_ {
                                Alias::Alias(an, aps, ab) => {
                                    not(null_p(aps))
                                }
                            }
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            })
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A type written in a module, its types and effects named as the
/// program names them, or as the printer has them.
pub fn module_qualified(scope: Quals, t: &'static Sexp) -> &'static Sexp {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            let found = filter(lambda1s(move |q: &'static Qual| {
                let tagcase_ = q;
                match *tagcase_ {
                    Qual::Qual(a, b, o) => {
                        string_eq_p(a, n)
                    }
                }
            }), scope);
            if null_p(found) {
                t
            } else {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Qual::Qual(a, b, o) => {
                        b
                    }
                }
            }
        }
        Sexp::Lst(xs, file, line, pos) => {
            if head_is_p(t, str_lit("select")) {
                t
            } else {
                lst(map(lambda1s(move |x: &'static Sexp| {
                    module_qualified(scope, x)
                }), xs), file, line, pos)
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// The types and effects module `m`'s items `fs` name, onto `scope`, the
/// first found first: a type `m..t`, an effect `m e`; an included
/// module's, its; an abbreviation of no parameters, of a family's
/// application, its expansion, else `m..t`, held opaque (`opaque-dts`).
pub fn module_scope(mut v: &'static Cv, mut all: Sexps, mut m: Str, mut fs: Sexps, mut scope: Quals) -> Quals {
    loop {
        if null_p(fs) {
            return scope;
        } else {
            let f = car(fs);
            let xs = {
                let tagcase_ = f;
                match *tagcase_ {
                    Sexp::Lst(ys, l1, l2, l3) => {
                        ys
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<&'static Sexp>()
                    }
                }
            };
            let more = if (head_is_p(f, str_lit("define-type")) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(t, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } && family_app_p(v, third(xs))) {
                the::<Quals>(kayak_rt::heap_cons(qual(sym_name(second(xs)), module_qualified(scope, third(xs)), false), kayak_rt::nil()))
            } else if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
                let t = head_name(v, second(xs));
                the::<Quals>(kayak_rt::heap_cons(qual(t, sym(string_append(m, string_append(str_lit(".."), t)), str_lit(""), 0i64), (head_is_p(f, str_lit("define-type")) && {
                    let tagcase_ = second(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                })), kayak_rt::nil()))
            } else if (head_is_p(f, str_lit("define-effect")) && i64_eq(size(xs), 3i64)) {
                let e = sym_name(second(xs));
                the::<Quals>(kayak_rt::heap_cons(qual(e, sym(string_append(m, string_append(str_lit(" "), e)), str_lit(""), 0i64), false), kayak_rt::nil()))
            } else if head_is_p(f, str_lit("hide")) {
                module_scope(v, all, m, cdr(xs), nil::<&'static Qual>())
            } else if (head_is_p(f, str_lit("include")) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let def = module_of(sym_name(second(xs)), all);
                if null_p(def) {
                    nil::<&'static Qual>()
                } else {
                    module_scope(v, all, sym_name(second(xs)), module_written(car(def)), nil::<&'static Qual>())
                }
            } else {
                nil::<&'static Qual>()
            };
            (fs, scope) = (cdr(fs), onto(more, scope));
            continue;
        }
    }
}

/// `v` with each `m..t` of `scope` a type of its name alone.
pub fn opaque_names(v: &'static Cv, scope: Quals) -> &'static Cv {
    let names = concat(map(lambda1s(move |q: &'static Qual| {
        let tagcase_ = q;
        match *tagcase_ {
            Qual::Qual(a, b, o) => {
                if o {
                    let tagcase_ = b;
                    match *tagcase_ {
                        Sexp::Sym(n, f, p) => {
                            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                } else {
                    nil::<Str>()
                }
            }
        }
    }), scope));
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at, ix, mk) => {
            cv(bs, onto(map(lambda1s(move |n: Str| {
                dt(n, nil::<Str>(), nil::<&'static Variant>())
            }), names), ds), als, es, here, group, file, line, fs, tv, at, ix, mk)
        }
    }
}

/// `cs` with each name's module, `m..`, taken off; `tok` the name being
/// read, reversed, and `acc` what is done, reversed.
pub fn dequalified(mut cs: Chars, mut tok: Chars, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return reverse(onto(tok, acc));
        } else if (char_eq_p(car(cs), '.') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '.')) {
            (cs, tok) = (cdr(cdr(cs)), nil::<char>());
            continue;
        } else if (char_eq_p(car(cs), ' ') || char_eq_p(car(cs), '(') || char_eq_p(car(cs), ')')) {
            (cs, tok, acc) = (cdr(cs), nil::<char>(), kayak_rt::heap_cons(car(cs), onto(tok, acc)));
            continue;
        } else {
            (cs, tok) = (cdr(cs), kayak_rt::heap_cons(car(cs), tok));
            continue;
        }
    }
}

/// Each of a module's items `fs`, as its type says it: its descriptions
/// (`descs`), or its values; "%none" for one not printed.
pub fn module_items_shown(v: &'static Cv, all: Sexps, scope: Quals, fs: Sexps, descs: bool) -> Strings {
    if null_p(fs) {
        nil::<Str>()
    } else {
        onto(module_item_shown(v, all, scope, car(fs), descs), module_items_shown(v, all, scope, cdr(fs), descs))
    }
}

pub fn module_item_shown(v: &'static Cv, all: Sexps, scope: Quals, f: &'static Sexp, descs: bool) -> Strings {
    let (xs, shown) = (items(f), lambda2s(move |t: &'static Sexp, tvars: Strings| {
        if written_mentions_p(t, kayak_rt::heap_cons(str_lit("%found"), kayak_rt::heap_cons(str_lit("->*"), kayak_rt::heap_cons(str_lit("moduleof"), kayak_rt::nil())))) {
            str_lit("%none")
        } else {
            list_to_string(dequalified(string_chars(show_ty(new_state(), parse_type(v, kayak_rt::heap_cons(str_lit("%keep-names"), written_tvars(tvars)), module_qualified(scope, t)))), nil::<char>(), nil::<char>()))
        }
    }));
    if head_is_p(f, str_lit("define-type")) {
        if not(descs) {
            nil::<Str>()
        } else {
            let tagcase_ = second(xs);
            match *tagcase_ {
                Sexp::Sym(t, f2, p2) => {
                    the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(desc "), string_append(t, string_append(str_lit(" "), string_append(shown(third(xs), nil::<Str>()), str_lit(")"))))), kayak_rt::nil()))
                }
                Sexp::Lst(hs, f2, l2, p2) => {
                    the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(desc "), string_append(sym_name(car(hs)), string_append(str_lit(" (dlambda "), string_append(show_sexp(lst(cdr(hs), str_lit(""), 0i64, 0i64)), string_append(str_lit(" "), string_append(shown(third(xs), family_params(v, second(xs))), str_lit("))"))))))), kayak_rt::nil()))
                }
                _ => {
                    let other = tagcase_;
                    the::<Strings>(kayak_rt::heap_cons(str_lit("%none"), kayak_rt::nil()))
                }
            }
        }
    } else if head_is_p(f, str_lit("define-generative")) {
        if descs {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(abs "), string_append(head_name(v, second(xs)), str_lit(" type)"))), kayak_rt::nil()))
        } else {
            nil::<Str>()
        }
    } else if (head_is_p(f, str_lit("define-effect")) && i64_eq(size(xs), 3i64)) {
        if descs {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(desc "), string_append(sym_name(second(xs)), string_append(str_lit(" "), string_append(show_effs(parse_effect(v, nil::<Str>(), module_qualified(scope, third(xs)))), str_lit(")"))))), kayak_rt::nil()))
        } else {
            nil::<Str>()
        }
    } else if ((head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) && i64_eq(size(xs), 4i64)) {
        if descs {
            nil::<Str>()
        } else {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("(val "), string_append(sym_name(second(xs)), string_append(str_lit(" "), string_append(poly_wrapped(third(xs), shown(written_body(third(xs)), written_binders(v, third(xs)))), str_lit(")"))))), kayak_rt::nil()))
        }
    } else if head_is_p(f, str_lit("define-rec")) {
        if descs {
            nil::<Str>()
        } else {
            map(lambda1s(move |g: &'static Sexp| {
                let gs = items(g);
                if i64_eq(size(gs), 3i64) {
                    string_append(str_lit("(val "), string_append(sym_name(car(gs)), string_append(str_lit(" "), string_append(poly_wrapped(second(gs), shown(written_body(second(gs)), written_binders(v, second(gs)))), str_lit(")")))))
                } else {
                    str_lit("%none")
                }
            }), cdr(xs))
        }
    } else if head_is_p(f, str_lit("hide")) {
        nil::<Str>()
    } else if (head_is_p(f, str_lit("include")) && i64_eq(size(xs), 2i64) && {
        let tagcase_ = second(xs);
        match *tagcase_ {
            Sexp::Sym(n, f2, p2) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        let def = module_of(sym_name(second(xs)), all);
        if null_p(def) {
            the::<Strings>(kayak_rt::heap_cons(str_lit("%none"), kayak_rt::nil()))
        } else {
            let fs = module_written(car(def));
            module_items_shown(v, all, module_scope(v, all, sym_name(second(xs)), fs, nil::<&'static Qual>()), fs, descs)
        }
    } else {
        the::<Strings>(kayak_rt::heap_cons(str_lit("%none"), kayak_rt::nil()))
    }
}

// Base types named (C165): an abbreviation of a base type, `(define-type
// num int)`, names it wherever Fixpt prints it, the latest one, a module's
// own for its own items, since Fixpt's types are shared and the latest
// abbreviation names the type.
pub enum Brn {
    Brn(Str, Str),
}

pub fn brn(f0: Str, f1: Str) -> &'static Brn {
    kayak_rt::heap_alloc(Brn::Brn(f0, f1))
}

pub type Brns = List<&'static Brn>;

pub fn base_names() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit("int"), kayak_rt::heap_cons(str_lit("nat"), kayak_rt::heap_cons(str_lit("i64"), kayak_rt::heap_cons(str_lit("u64"), kayak_rt::heap_cons(str_lit("i32"), kayak_rt::heap_cons(str_lit("u32"), kayak_rt::heap_cons(str_lit("i16"), kayak_rt::heap_cons(str_lit("u16"), kayak_rt::heap_cons(str_lit("i8"), kayak_rt::heap_cons(str_lit("u8"), kayak_rt::heap_cons(str_lit("f64"), kayak_rt::heap_cons(str_lit("f32"), kayak_rt::heap_cons(str_lit("bool"), kayak_rt::heap_cons(str_lit("char"), kayak_rt::heap_cons(str_lit("string"), kayak_rt::heap_cons(str_lit("unit"), kayak_rt::heap_cons(str_lit("symbol"), kayak_rt::heap_cons(str_lit("datum"), kayak_rt::nil()))))))))))))))))))
    })
}

pub fn brn_find(bs: Brns, x: Str) -> Str {
    let found = filter(lambda1s(move |b: &'static Brn| {
        let tagcase_ = b;
        match *tagcase_ {
            Brn::Brn(k, n) => {
                string_eq_p(k, x)
            }
        }
    }), bs);
    if null_p(found) {
        str_lit("")
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Brn::Brn(k, n) => {
                n
            }
        }
    }
}

/// Of definitions `fs`, onto `renames` (a base type to its name, the
/// latest first), given `aliases` (an abbreviation to the base type it
/// is): each `(define-type t b)`, `b` a base type or an abbreviation of
/// one.
pub fn base_renames(mut fs: Sexps, mut aliases: Brns, mut renames: Brns) -> Brns {
    loop {
        if null_p(fs) {
            return renames;
        } else {
            let f = car(fs);
            let xs = {
                let tagcase_ = f;
                match *tagcase_ {
                    Sexp::Lst(ys, l1, l2, l3) => {
                        ys
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<&'static Sexp>()
                    }
                }
            };
            let base = if (head_is_p(f, str_lit("define-type")) && i64_eq(size(xs), 3i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(t, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } && {
                let tagcase_ = third(xs);
                match *tagcase_ {
                    Sexp::Sym(b, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let b = sym_name(third(xs));
                if string_member_p(b, base_names()) {
                    b
                } else {
                    brn_find(aliases, b)
                }
            } else if (head_is_p(f, str_lit("define-type")) && i64_eq(size(xs), 3i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(t, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } && head_is_p(third(xs), str_lit("select")) && i64_eq(size(items(third(xs))), 3i64)) {
                // A module's type, `m..t`, named as the abbreviation of it names
                // it (C172).
                string_append(show_sexp(second(items(third(xs)))), string_append(str_lit(".."), show_sexp(third(items(third(xs))))))
            } else {
                str_lit("")
            };
            if string_eq_p(base, str_lit("")) {
                fs = cdr(fs);
                continue;
            } else {
                (fs, aliases, renames) = (cdr(fs), kayak_rt::heap_cons(brn(sym_name(second(xs)), base), aliases), kayak_rt::heap_cons(brn(base, sym_name(second(xs))), renames));
                continue;
            }
        }
    }
}

/// Onto `aliases`, each of `fs`'s abbreviations of a base type.
pub fn base_aliases(mut fs: Sexps, mut aliases: Brns) -> Brns {
    loop {
        if null_p(fs) {
            return aliases;
        } else {
            let f = car(fs);
            let xs = {
                let tagcase_ = f;
                match *tagcase_ {
                    Sexp::Lst(ys, l1, l2, l3) => {
                        ys
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<&'static Sexp>()
                    }
                }
            };
            let base = if (head_is_p(f, str_lit("define-type")) && i64_eq(size(xs), 3i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(t, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } && {
                let tagcase_ = third(xs);
                match *tagcase_ {
                    Sexp::Sym(b, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let b = sym_name(third(xs));
                if string_member_p(b, base_names()) {
                    b
                } else {
                    brn_find(aliases, b)
                }
            } else {
                str_lit("")
            };
            (fs, aliases) = (cdr(fs), if string_eq_p(base, str_lit("")) {
                aliases
            } else {
                kayak_rt::heap_cons(brn(sym_name(second(xs)), base), aliases)
            });
            continue;
        }
    }
}

/// A token read, reversed, renamed if it is a base type named.
pub fn token_renamed(t: Chars, renames: Brns) -> Chars {
    let n = brn_find(renames, list_to_string(reverse(t)));
    if string_eq_p(n, str_lit("")) {
        t
    } else {
        reverse(string_chars(n))
    }
}

/// `cs` with each token a base type renamed; `tok` the token being read,
/// reversed, `acc` what is done, reversed.
pub fn tokens_renamed(mut cs: Chars, mut tok: Chars, mut renames: Brns, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return reverse(onto(token_renamed(tok, renames), acc));
        } else if (char_eq_p(car(cs), ' ') || char_eq_p(car(cs), '(') || char_eq_p(car(cs), ')')) {
            (cs, tok, acc) = (cdr(cs), nil::<char>(), kayak_rt::heap_cons(car(cs), onto(token_renamed(tok, renames), acc)));
            continue;
        } else {
            (cs, tok) = (cdr(cs), kayak_rt::heap_cons(car(cs), tok));
            continue;
        }
    }
}

pub fn base_renamed(line: Str, renames: Brns) -> Str {
    if null_p(renames) {
        line
    } else {
        list_to_string(tokens_renamed(string_chars(line), nil::<char>(), renames, nil::<char>()))
    }
}

pub fn visible_items(fs: Sexps) -> Sexps {
    filter(lambda1s(move |f: &'static Sexp| {
        not(head_is_p(f, str_lit("hide")))
    }), fs)
}

/// Each description `parts`, its body named with the module's own
/// abbreviations of base types before it.
pub fn descs_renamed(parts: Strings, own: Sexps, aliases: Brns, renames: Brns) -> Strings {
    if null_p(parts) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons(if has_prefix_p(car(parts), str_lit("(desc ")) {
            base_renamed(car(parts), base_renames(items_before(own, car(cdr(text_words(car(parts))))), aliases, renames))
        } else {
            car(parts)
        }, descs_renamed(cdr(parts), own, aliases, renames))
    }
}

pub fn items_before(fs: Sexps, name: Str) -> Sexps {
    if null_p(fs) {
        nil::<&'static Sexp>()
    } else if ((head_is_p(car(fs), str_lit("define-type")) || head_is_p(car(fs), str_lit("define-generative")) || head_is_p(car(fs), str_lit("define-datatype"))) && {
        let tagcase_ = second(items(car(fs)));
        match *tagcase_ {
            Sexp::Sym(t, f, p) => {
                string_eq_p(t, name)
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        nil::<&'static Sexp>()
    } else {
        kayak_rt::heap_cons(car(fs), items_before(cdr(fs), name))
    }
}

/// The modules a module's items include, hidden or not: what making it
/// reads.
pub fn included_modules(fs: Sexps) -> Strings {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("include")) && {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(n, f2, p2) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }) {
            the::<Strings>(kayak_rt::heap_cons(sym_name(second(items(f))), kayak_rt::nil()))
        } else if head_is_p(f, str_lit("hide")) {
            included_modules(cdr(items(f)))
        } else {
            nil::<Str>()
        }
    }), fs))
}

pub fn field_labels(i: i64, ts: Tys) -> Strings {
    if null_p(ts) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons(i64_to_string(i), field_labels(i64_plus(i, 1i64), cdr(ts)))
    }
}

/// A module's type as Fixpt prints it (C172): a datatype of its own a
/// description of its sum, `(productof (1 T) ...)` each variant's fields;
/// its abstract types its own, unqualified.
pub fn module_shown(v: &'static Cv, m: Str, t: &'static Ty) -> &'static Ty {
    let sums = concat(map(lambda1s(move |x: &'static Ty| {
        if string_eq_p(mitem_kind(x), str_lit("%abs")) {
            let found = filter(lambda1s(move |d: &'static Dt| {
                let tagcase_ = d;
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        (string_eq_p(n, string_append(m, string_append(str_lit(".."), mitem_name(x)))) && null_p(ps) && not(null_p(vs)))
                    }
                }
            }), cv_dts(v));
            if null_p(found) {
                nil::<&'static Ty>()
            } else {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        the::<Tys>(kayak_rt::heap_cons(ty_data(string_append(str_lit("%desc "), mitem_name(x)), kayak_rt::heap_cons(ty_shape(false, map(lambda1s(move |w: &'static Variant| {
                            let tagcase_ = w;
                            match *tagcase_ {
                                Variant::Variant(tag, fs) => {
                                    tag
                                }
                            }
                        }), vs), map(lambda1s(move |w: &'static Variant| {
                            let tagcase_ = w;
                            match *tagcase_ {
                                Variant::Variant(tag, fs) => {
                                    ty_shape(true, field_labels(1i64, fs), fs)
                                }
                            }
                        }), vs)), kayak_rt::nil())), kayak_rt::nil()))
                    }
                }
            }
        } else {
            nil::<&'static Ty>()
        }
    }), mtype_items(t)));
    let froms = map(lambda1s(move |d: &'static Ty| {
        string_append(m, string_append(str_lit(".."), mitem_name(d)))
    }), sums);
    let tos = map(lambda1s(move |d: &'static Ty| {
        let tagcase_ = d;
        match *tagcase_ {
            Ty::TyData(k, a) => {
                car(a)
            }
            _ => {
                let other = tagcase_;
                ty_unit()
            }
        }
    }), sums);
    let items2 = map(lambda1s(move |x: &'static Ty| {
        let mine = filter(lambda1s(move |d: &'static Ty| {
            string_eq_p(mitem_name(d), mitem_name(x))
        }), sums);
        if (string_eq_p(mitem_kind(x), str_lit("%abs")) && not(null_p(mine))) {
            car(mine)
        } else {
            data_replaced(froms, tos, x)
        }
    }), mtype_items(t));
    own_abstract(m, ty_data(str_lit("%mtype"), items2))
}

/// The type names a module's items define, hidden or not.
pub fn module_names_given(fs: Sexps) -> Strings {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if ((head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) && i64_gt(size(items(f)), 2i64)) {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(n, f2, p2) => {
                    the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                }
                Sexp::Lst(ys, f2, l2, p2) => {
                    the::<Strings>(kayak_rt::heap_cons(sym_name(car(ys)), kayak_rt::nil()))
                }
                _ => {
                    let other = tagcase_;
                    nil::<Str>()
                }
            }
        } else if head_is_p(f, str_lit("hide")) {
            module_names_given(cdr(items(f)))
        } else {
            nil::<Str>()
        }
    }), fs))
}

pub fn module_line(v: &'static Cv, all: Sexps, form: &'static Sexp) -> Strings {
    let (m, fs) = (sym_name(second(items(form))), if head_is_p(third(items(form)), str_lit("module")) {
        module_written(form)
    } else {
        nil::<&'static Sexp>()
    });
    if null_p(fs) {
        nil::<Str>()
    } else {
        let scope = if has_prefix_p(datum_file(form), str_lit("fx26:")) {
            nil::<&'static Qual>()
        } else {
            module_scope(v, all, m, fs, nil::<&'static Qual>())
        };
        let w = opaque_names(v, scope);
        let top = base_aliases(filter(lambda1s(move |f: &'static Sexp| {
            not(module_def_p(f))
        }), all), nil::<&'static Brn>());
        let own = visible_items(fs);
        let outer = filter(lambda1s(move |b: &'static Brn| {
            let tagcase_ = b;
            match *tagcase_ {
                Brn::Brn(k, n) => {
                    not(string_member_p(n, module_names_given(fs)))
                }
            }
        }), base_renames(filter(lambda1s(move |f: &'static Sexp| {
            not(module_def_p(f))
        }), all), nil::<&'static Brn>(), nil::<&'static Brn>()));
        let parts = if has_prefix_p(datum_file(form), str_lit("fx26:")) {
            the::<Strings>(kayak_rt::heap_cons(str_lit("%none"), kayak_rt::nil()))
        } else {
            onto(descs_renamed(module_items_shown(w, all, scope, fs, true), own, top, outer), map(lambda1s(move |p: Str| {
                base_renamed(p, base_renames(own, top, outer))
            }), module_items_shown(w, all, scope, fs, false)))
        };
        let included = sorted_strings(filter(lambda1s(move |n: Str| {
            not(has_prefix_p(n, str_lit("made--")))
        }), included_modules(fs)));
        if any_p(lambda1s(move |p: Str| {
            string_has_p(p, str_lit("%none"))
        }), parts) {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("define "), string_append(m, string_append(str_lit(" : "), string_append(base_renamed(show_ty(new_state(), module_shown(v, m, expressions::module_type_of(v, m))), outer), string_append(str_lit(" ! "), if null_p(included) {
                str_lit("pure")
            } else {
                string_append(str_lit("(read (globals "), string_append(words_of(included), str_lit("))")))
            }))))), kayak_rt::nil()))
        } else {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%M define "), string_append(m, string_append(str_lit(" : (moduleof"), string_append(run_together(map(lambda1s(move |p: Str| {
                string_append(str_lit(" "), p)
            }), parts)), string_append(str_lit(") ! "), if null_p(included) {
                str_lit("pure")
            } else {
                string_append(str_lit("(read (globals "), string_append(words_of(included), str_lit("))")))
            }))))), kayak_rt::nil()))
        }
    }
}

/// What `fixpt check` writes of `form`, checked: `v`, the checker's
/// environment after it; `all`, the program's forms.
pub fn form_lines(v: &'static Cv, all: Sexps, form: &'static Sexp) -> Strings {
    if ((head_is_p(form, str_lit("define")) || module_def_p(form)) && i64_gt(size(items(form)), 2i64) && {
        let tagcase_ = second(items(form));
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                has_prefix_p(n, str_lit("made--"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A module kfx's reader made (C88, C90), Fixpt's of no name: no line (C172).
        nil::<Str>()
    } else if module_def_p(form) {
        module_line(v, all, form)
    } else if (head_is_p(form, str_lit("define")) && {
        let tagcase_ = second(items(form));
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                has_prefix_p(n, str_lit("%shared:"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A loaded file's value, a hidden global (C171): Fixpt prints none.
        nil::<Str>()
    } else if (head_is_p(form, str_lit("define")) || head_is_p(form, str_lit("define*"))) {
        let xs = items(form);
        kayak_rt::heap_cons(bound_line(v, binder_name(second(xs)), if not(i64_eq(size(xs), 4i64)) {
            no_form()
        } else if head_is_p(third(xs), str_lit("proves")) {
            proves_type(v, third(xs))
        } else {
            third(xs)
        }, value_effect(v, binder_name(second(xs)), last(xs))), kayak_rt::nil())
    } else if head_is_p(form, str_lit("define-rec")) {
        map(lambda1s(move |g: &'static Sexp| {
            bound_line(v, sym_name(car(items(g))), if i64_eq(size(items(g)), 3i64) {
                second(items(g))
            } else {
                no_form()
            }, str_lit("pure"))
        }), cdr(items(form)))
    } else if head_is_p(form, str_lit("define-datatype")) {
        map(lambda1s(move |g: &'static Sexp| {
            bound_line(v, sym_name(car(items(g))), no_form(), str_lit("pure"))
        }), cdr(cdr(items(form))))
    } else if head_is_p(form, str_lit("define-generative")) {
        // Its conversions; a family's in a `poly` of its parameters, as written
        // (C179: Fixpt prints `(poly ((a type)) (subr pure (...) (tree a)))`).
        let n = binder_name(second(items(form)));
        let w = {
            let tagcase_ = unmarked(second(items(form)));
            match *tagcase_ {
                Sexp::Lst(xs, f, l, p) => {
                    lst(kayak_rt::heap_cons(sym(str_lit("poly"), str_lit(""), 0i64), kayak_rt::heap_cons(lst(cdr(xs), str_lit(""), 0i64, 0i64), kayak_rt::heap_cons(no_form(), kayak_rt::nil()))), str_lit(""), 0i64, 0i64)
                }
                _ => {
                    let other = tagcase_;
                    no_form()
                }
            }
        };
        kayak_rt::heap_cons(generative_line(v, string_append(str_lit("up-"), n), w), kayak_rt::heap_cons(generative_line(v, string_append(str_lit("down-"), n), w), kayak_rt::nil()))
    } else if (head_is_p(form, str_lit("define-type")) || head_is_p(form, str_lit("define-effect")) || head_is_p(form, str_lit("define-convention"))) {
        nil::<Str>()
    } else {
        let tagcase_ = expressions::synth(at(v, str_lit("a top-level expression"), nil::<Str>()), new_state(), form);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let shown = show_ty(s, t);
                if string_has_p(shown, str_lit("%fresh")) {
                    kayak_rt::heap_cons(string_append(call_shown(v, all, form, list_to_string(chars_replaced(string_chars(shown), string_chars(str_lit("%fresh")), string_chars(str_lit("@r.1")), nil::<char>()))), string_append(str_lit(" ! "), show_effs(settled_effs(s, kayak_rt::heap_cons(str_lit("alloc:@r.1"), es))))), kayak_rt::nil())
                } else {
                    kayak_rt::heap_cons(string_append(call_shown(v, all, form, shown), string_append(str_lit(" ! "), show_effs(settled_effs(s, es)))), kayak_rt::nil())
                }
            }
        }
    }
}

// Recursive types printed as Fixpt prints them (C174; its `unparse.rs`):
// a `(mu %x ...)`'s variable named by the depth of the type it stands for,
// counted in the type constructors around it, `%3`. Each line's text read
// as tokens, parentheses, spaces and words, kept; each frame a list's: `N`
// a constructor's, `-` another's, `M x k` a mu's.
pub fn mu_nodes() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit("subr"), kayak_rt::heap_cons(str_lit("poly"), kayak_rt::heap_cons(str_lit("productof"), kayak_rt::heap_cons(str_lit("sumof"), kayak_rt::heap_cons(str_lit("listof"), kayak_rt::heap_cons(str_lit("pairof"), kayak_rt::heap_cons(str_lit("union"), kayak_rt::heap_cons(str_lit("moduleof"), kayak_rt::heap_cons(str_lit("ref"), kayak_rt::heap_cons(str_lit("icell"), kayak_rt::heap_cons(str_lit("arrayof"), kayak_rt::heap_cons(str_lit("flatarrayof"), kayak_rt::heap_cons(str_lit("narrayof"), kayak_rt::heap_cons(str_lit("bloblet"), kayak_rt::heap_cons(str_lit("vectorof"), kayak_rt::heap_cons(str_lit("addr"), kayak_rt::heap_cons(str_lit("inbox"), kayak_rt::heap_cons(str_lit("mark-key"), kayak_rt::heap_cons(str_lit("prompt-tag"), kayak_rt::heap_cons(str_lit("composable"), kayak_rt::heap_cons(str_lit("oneshot"), kayak_rt::heap_cons(str_lit("vsubr"), kayak_rt::heap_cons(str_lit("blobref"), kayak_rt::heap_cons(str_lit("nlist"), kayak_rt::heap_cons(str_lit("dlambda"), kayak_rt::heap_cons(str_lit("bytevectorof"), kayak_rt::nil()))))))))))))))))))))))))))
    })
}

/// `cs` as tokens, reversed onto `acc`; `word`, the one being read, reversed.
pub fn line_tokens(mut cs: Chars, mut word: Chars, mut acc: Strings) -> Strings {
    loop {
        if null_p(cs) {
            if null_p(word) {
                return acc;
            } else {
                return kayak_rt::heap_cons(rev_to_string(word), acc);
            }
        } else if (char_eq_p(car(cs), '(') || char_eq_p(car(cs), ')') || char_eq_p(car(cs), ' ')) {
            (cs, word, acc) = (cdr(cs), nil::<char>(), kayak_rt::heap_cons(list_to_string(kayak_rt::heap_cons(car(cs), kayak_rt::nil())), if null_p(word) {
                acc
            } else {
                kayak_rt::heap_cons(rev_to_string(word), acc)
            }));
            continue;
        } else {
            (cs, word) = (cdr(cs), kayak_rt::heap_cons(car(cs), word));
            continue;
        }
    }
}

pub fn mu_renamed(mut w: Str, mut frames: Strings) -> Str {
    loop {
        if null_p(frames) {
            return w;
        } else if has_prefix_p(car(frames), string_append(str_lit("M "), string_append(w, str_lit(" ")))) {
            return after_prefix(car(frames), string_append(str_lit("M "), string_append(w, str_lit(" "))));
        } else {
            frames = cdr(frames);
            continue;
        }
    }
}

pub fn mu_node_count(frames: Strings) -> i64 {
    if null_p(frames) {
        0i64
    } else {
        i64_plus(if string_eq_p(car(frames), str_lit("N")) {
            1i64
        } else {
            0i64
        }, mu_node_count(cdr(frames)))
    }
}

/// `opened`: the token before was `(`; `mu`, a mu's variable awaited
/// (`?`) or none (``).
pub fn mu_numbered_tokens(mut ts: Strings, mut frames: Strings, mut opened: bool, mut mu: Str, mut acc: Strings) -> Strings {
    loop {
        if null_p(ts) {
            return reverse(acc);
        } else {
            let t = car(ts);
            if string_eq_p(t, str_lit(" ")) {
                (ts, acc) = (cdr(ts), kayak_rt::heap_cons(t, acc));
                continue;
            } else if string_eq_p(t, str_lit("(")) {
                if opened {
                    (ts, frames, opened, mu, acc) = (cdr(ts), kayak_rt::heap_cons(str_lit("-"), frames), true, str_lit(""), kayak_rt::heap_cons(t, acc));
                    continue;
                } else {
                    (ts, opened, mu, acc) = (cdr(ts), true, str_lit(""), kayak_rt::heap_cons(t, acc));
                    continue;
                }
            } else if string_eq_p(t, str_lit(")")) {
                (ts, frames, opened, mu, acc) = (cdr(ts), if (opened || null_p(frames)) {
                    frames
                } else {
                    cdr(frames)
                }, false, str_lit(""), kayak_rt::heap_cons(t, acc));
                continue;
            } else if opened {
                if string_eq_p(t, str_lit("mu")) {
                    (ts, frames, opened, mu, acc) = (cdr(ts), kayak_rt::heap_cons(str_lit("-"), frames), false, str_lit("?"), kayak_rt::heap_cons(t, acc));
                    continue;
                } else if string_member_p(t, mu_nodes()) {
                    (ts, frames, opened, mu, acc) = (cdr(ts), kayak_rt::heap_cons(str_lit("N"), frames), false, str_lit(""), kayak_rt::heap_cons(t, acc));
                    continue;
                } else {
                    (ts, frames, opened, mu, acc) = (cdr(ts), kayak_rt::heap_cons(str_lit("-"), frames), false, str_lit(""), kayak_rt::heap_cons(t, acc));
                    continue;
                }
            } else if string_eq_p(mu, str_lit("?")) {
                let k = string_append(str_lit("%"), i64_to_string(i64_plus(mu_node_count(frames), 1i64)));
                (ts, frames, opened, mu, acc) = (cdr(ts), kayak_rt::heap_cons(string_append(str_lit("M "), string_append(t, string_append(str_lit(" "), k))), cdr(frames)), false, str_lit(""), kayak_rt::heap_cons(k, acc));
                continue;
            } else {
                (ts, opened, mu, acc) = (cdr(ts), false, str_lit(""), kayak_rt::heap_cons(mu_renamed(t, frames), acc));
                continue;
            }
        }
    }
}

pub fn chars_within_p(mut cs: Chars, mut from: Chars) -> bool {
    loop {
        if null_p(cs) {
            return false;
        } else if chars_start_p(cs, from) {
            return true;
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn mu_numbered(l: Str) -> Str {
    if chars_within_p(string_chars(l), string_chars(str_lit("(mu "))) {
        run_together(mu_numbered_tokens(reverse(line_tokens(string_chars(l), nil::<char>(), nil::<Str>())), nil::<Str>(), false, str_lit(""), nil::<Str>()))
    } else {
        l
    }
}

pub fn lines_checked(v: &'static Cv, all: Sexps, forms: Sexps) -> Strings {
    if null_p(forms) {
        nil::<Str>()
    } else {
        let tagcase_ = check_tops(v, kayak_rt::heap_cons(car(forms), kayak_rt::nil()), nil::<&'static Typed>());
        match *tagcase_ {
            Elab::Elab(v2, found) => {
                onto(form_lines(v2, all, car(forms)), lines_checked(v2, all, cdr(forms)))
            }
        }
    }
}

pub fn lines_text(ls: Strings) -> Str {
    if null_p(ls) {
        str_lit("")
    } else {
        string_append(car(ls), string_append(str_lit("\n"), lines_text(cdr(ls))))
    }
}

pub fn check_command(paths: Strings) -> Int {
    let forms = read_files(paths);
    let empty = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), nil::<&'static Alias>(), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64, bempty(), nil::<&'static Bind>());
    let start = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), declare_types(empty, forms, nil::<&'static Alias>()), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64, bempty(), nil::<&'static Bind>());
    let types = type_names_free(start, forms);
    let named = {
        let tagcase_ = start;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at, ix, mk) => {
                cv(bs, datatype_names(start, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at, ix, mk)
            }
        }
    };
    let typed = {
        let tagcase_ = named;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at, ix, mk) => {
                cv(bs, declare_datatypes(named, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at, ix, mk)
            }
        }
    };
    let v = with_binds(typed, prim_binds(typed));
    let names = base_renames(filter(lambda1s(move |f: &'static Sexp| {
        not(module_def_p(f))
    }), forms), nil::<&'static Brn>(), nil::<&'static Brn>());
    say(lines_text(map(lambda1s(move |l: Str| {
        mu_numbered(if has_prefix_p(l, str_lit("%M ")) {
            after_prefix(l, str_lit("%M "))
        } else {
            base_renamed(l, names)
        })
    }), lines_checked(v, forms, forms))));
    int_lit(0)
}

pub fn main() -> Int {
    let r#as = the::<Strings>(args());
    if (null_p(r#as) || string_eq_p(car(r#as), str_lit("repl"))) {
        (&tasks::repl_x)(history_of(r#as))
    } else if (string_eq_p(car(r#as), str_lit("--keys")) && not(null_p(cdr(r#as))) && null_p(cdr(cdr(r#as)))) {
        (&tasks::scripted_x)(car(cdr(r#as)))
    } else if (string_eq_p(car(r#as), str_lit("--check")) && not(null_p(cdr(r#as)))) {
        check_command(cdr(r#as))
    } else {
        engine_main()
    }
}

